SELECT ?show ?host ?numberOfShowsHosted WHERE {
  ?appearance wdt:P161 wd:Q123456;  # Replace Q123456 with Paul Melba's Wikidata ID
              wdt:P1343 ?show.
  ?show wdt:P364 wd:Q145.           # Country: United Kingdom (British version)
  ?show wdt:P86 ?host.
  ?host wdt:P166 ?award.
  OPTIONAL {
    ?host wdt:P2532 ?numberOfShowsHosted.
  }
  FILTER(?numberOfShowsHosted = 23)
} LIMIT 10

SELECT ?show ?host ?band WHERE {
  ?show wdt:P31 wd:Q15416;                   # ?show is a television show
        rdfs:label "You Can't See Me"@en;
        wdt:P364 ?host.                      # ?host is associated with the show (check property for host)
  ?host wdt:P136 ?band.                      # ?host is a member of ?band (musical group)
  ?band wdt:P527 ?member.                    # ?band has members
  ?member rdfs:label "Defari"@en.            # One member is Defari
} LIMIT 10

# Alternatively, adjust properties to ensure host and band membership relationships are correctly queried.

SELECT ?composer ?composerDebutFilm WHERE {
  # Get the composer of the film Veyyil
  ?veyyil wdt:P31 wd:Q11424;  # instance of film
           rdfs:label "Veyyil"@en;
           wdt:P86 ?composer.   # composer

  # Get the debut film of the composer (first film they composed music for)
  ?composer wdt:P166 ?award. OPTIONAL {
    ?composer p:P57 ?filmRole.
    ?filmRole ps:P57 ?film.
    ?film wdt:P571 ?releaseDate.
  }
  # Alternatively, get earliest film with composer role
  {
    SELECT ?composer (MIN(?releaseDate) AS ?composerDebutDate) ?composerDebutFilm WHERE {
      ?composer p:P86 ?statement.
      ?statement ps:P86 ?composerDebutFilm.
      ?composerDebutFilm wdt:P571 ?releaseDate.
    } GROUP BY ?composer
  }

  # Check if Ashrita Shetty acted in any film composed by the composer
  ?ashrita wdt:P31 wd:Q5; # instance of human
           rdfs:label "Ashrita Shetty"@en.
  ?film wdt:P86 ?composer;
        wdt:P161 ?ashrita. # cast member

  FILTER(?composerDebutFilm = ?veyyil)
}
LIMIT 1

