SELECT ?station ?terminus ?owner ?terminus_location ?terminus_county WHERE {
  ?station wdt:P31 wd:Q55488;             # station instance
           rdfs:label "Quaker Ridge"@en;
           wdt:P127 ?owner.

  ?owner wdt:P31 wd:Q783794.

  ?terminus wdt:P31 wd:Q55488;
            wdt:P449 ?owner;
            wdt:P17 wd:Q30;                  # located in United States
            wdt:P131 ?terminus_location.

  ?terminus_location wdt:P131* ?terminus_county.

  FILTER(CONTAINS(LCASE(STR(?terminus)), "terminus"))
} LIMIT 10

