SELECT ?actor ?actorName ?film2 ?director ?directorName WHERE {
  ?film1 rdf:type dbo:Film ;
         rdfs:label "Office"@en ;
         dbo:starring ?actor .
  ?actor rdfs:label ?actorName .
  ?film1 dbo:starring ?coActor .
  ?coActor rdfs:label "Go Ah-sung"@en .
  ?actor != ?coActor .
  ?film2 rdf:type dbo:Film ;
         rdfs:label "The Deal"@en ;
         dbo:starring ?actor ;
         dbo:director ?director .
  ?director rdfs:label ?directorName .
}

SELECT ?host ?totalShows WHERE {
  # Query to find British TV shows featuring Paul Melba
  ?show a dbo:TelevisionShow ;
        dbo:country dbr:United_Kingdom ;
        dbo:starring ?actor ;
        dbo:host ?host .
  ?actor foaf:name "Paul Melba"@en .

  # Count the number of shows hosted by this host
  {
    SELECT ?host (COUNT(DISTINCT ?showHosted) AS ?totalShows) WHERE {
      ?showHosted dbo:host ?host .
    }
    GROUP BY ?host
  }
} LIMIT 1

